/* MOTI GO Marketplace — módulo aislado. No escribe en colecciones de Mandaditos. */
import { auth, db, storage } from '../js/firebase-config.js';
import { getApp } from 'https://www.gstatic.com/firebasejs/12.0.0/firebase-app.js';
import { getFunctions, httpsCallable } from 'https://www.gstatic.com/firebasejs/12.0.0/firebase-functions.js';
import { getMessaging, getToken, onMessage, isSupported } from 'https://www.gstatic.com/firebasejs/12.0.0/firebase-messaging.js';
import {
  onAuthStateChanged, signInWithEmailAndPassword, createUserWithEmailAndPassword,
  signOut, updateProfile
} from 'https://www.gstatic.com/firebasejs/12.0.0/firebase-auth.js';
import {
  collection, doc, getDoc, getDocs, addDoc, setDoc, updateDoc, deleteDoc,
  query, where, orderBy, limit, onSnapshot, serverTimestamp, Timestamp, writeBatch
} from 'https://www.gstatic.com/firebasejs/12.0.0/firebase-firestore.js';
import { ref as storageRef, uploadBytesResumable, getDownloadURL } from 'https://www.gstatic.com/firebasejs/12.0.0/firebase-storage.js';

const functions = getFunctions(getApp(), 'us-central1');
const callCreateCheckout = httpsCallable(functions, 'marketplaceCrearCheckout');
const callCreatePickupRoute = httpsCallable(functions, 'marketplaceCrearRutaRecoleccion');
const callCreateDeliveryRoutes = httpsCallable(functions, 'marketplaceCrearRutasEntrega');
const callMarkPaymentReturn = httpsCallable(functions, 'marketplaceConsultarPagoRegreso');
const callStartMpOAuth = httpsCallable(functions, 'marketplaceIniciarOAuth');
const callMpConnectionStatus = httpsCallable(functions, 'marketplaceEstadoConexionMP');
const callConfirmWarehousePickup = httpsCallable(functions, 'marketplaceConfirmarRecogidaAlmacen');
const VAPID_KEY = ''; // Pegar aquí la clave pública Web Push de Firebase (no es una clave privada).
const $ = (id) => document.getElementById(id);
const money = (n) => new Intl.NumberFormat('es-MX', {style:'currency',currency:'MXN'}).format(Number(n)||0);
const esc = (s='') => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate = (v) => { try { const d = v?.toDate ? v.toDate() : (v instanceof Date ? v : new Date(v)); return Number.isNaN(d.getTime()) ? 'Fecha pendiente' : d.toLocaleDateString('es-MX',{day:'numeric',month:'short',year:'numeric'}); } catch { return 'Fecha pendiente'; } };
const fmtDateTime = (v) => { try { const d = v?.toDate ? v.toDate() : new Date(v); return Number.isNaN(d.getTime()) ? '' : d.toLocaleString('es-MX',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}); } catch { return ''; } };
const placeholder = (name='image') => `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="600" height="450" viewBox="0 0 600 450"><rect width="600" height="450" fill="#eef4ef"/><g fill="#8aa994"><circle cx="300" cy="180" r="55"/><path d="M190 310c12-62 54-91 110-91s98 29 110 91"/></g><text x="300" y="375" font-family="Arial" font-size="23" text-anchor="middle" fill="#5f7868">${esc(name).slice(0,28)}</text></svg>`)}`;
const statusLabels = {
  pendiente_pago:'Pendiente de pago', pago_en_revision:'Verificando pago', pagado:'Pago confirmado',
  esperando_vendedores:'Esperando a vendedores', recepcion_parcial:'Recepción parcial',
  esperando_recoleccion:'Esperando recolección', en_recoleccion:'En recolección',
  recibido_almacen:'Recibido en almacén', listo_para_ruta:'Listo para ruta', programado:'Entrega programada',
  en_reparto:'En reparto', entregado:'Entregado', listo_para_recoger:'Listo para recoger en almacén',
  recogido_cliente:'Recogido por cliente', incidencia:'Incidencia', cancelacion_solicitada:'Cancelación solicitada',
  cancelado:'Cancelado', reembolso_pendiente:'Reembolso pendiente', pendiente_preparacion:'Pendiente de preparación', en_preparacion:'En preparación', preparado:'Preparado', asignado_recoleccion:'Recolección asignada', recogido_por_motigo:'Recogido por MOTI GO', reembolsado:'Reembolsado'
};
const state = {
  user:null, profile:null, role:null, mainAdmin:false, products:[], sellerProducts:[], cart:loadJSON('motiMpCart',[]), favorites:new Set(loadJSON('motiMpFavorites',[])),
  orders:[], notifications:[], sellerRequests:[], allRequests:[], allOrders:[], routes:[], opsRoutes:[], roles:[], operationConfig:null, view:'inicio', category:'todos', search:'', selectedRating:5,
  unsubs:[], productUnsub:null, orderUnsub:null, notificationUnsub:null, requestUnsub:null, roleUnsub:null, profileUnsub:null, sellerProductsUnsub:null, opsRequestUnsub:null, opsRouteUnsub:null, productsUnsub:null, notificationPanel:false, activeSlide:0, opTab:'almacen', cameraStream:null, cameraScanActive:false
};
function loadJSON(key, fallback){ try { const v=JSON.parse(localStorage.getItem(key)); return v ?? fallback; } catch { return fallback; } }
function saveJSON(key,value){ try{localStorage.setItem(key,JSON.stringify(value));}catch{} }
function toast(message,type='success'){ const node=document.createElement('div');node.className=`toast ${type==='error'?'error':type==='warning'?'warning':''}`;node.textContent=message;$('toastRegion').append(node);setTimeout(()=>node.remove(),4500); }
function setBusy(button,busy,label='Procesando…'){ if(!button)return; if(busy){button.dataset.oldText=button.innerHTML;button.disabled=true;button.innerHTML=`<span class="material-symbols-outlined">progress_activity</span>${label}`;}else{button.disabled=false;if(button.dataset.oldText)button.innerHTML=button.dataset.oldText;} }
function openModal(html,wide=false){ stopWarehouseCamera();const root=$('modalRoot');root.innerHTML=`<div class="modal-card ${wide?'wide':''}"><button class="icon-btn modal-close" data-close-modal aria-label="Cerrar"><span class="material-symbols-outlined">close</span></button>${html}</div>`;root.classList.remove('hidden');root.querySelectorAll('[data-close-modal]').forEach(b=>b.addEventListener('click',closeModal));root.onclick=e=>{if(e.target===root)closeModal();}; }
function closeModal(){ stopWarehouseCamera();$('modalRoot').classList.add('hidden');$('modalRoot').innerHTML=''; }
function showView(view,updateUrl=true){ if(!['inicio','catalogo','pedidos','favoritos','vender','operacion'].includes(view))view='inicio';state.view=view;document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id===`view-${view}`));document.querySelectorAll('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.view===view));if(updateUrl){const u=new URL(location.href);u.searchParams.set('vista',view);history.replaceState({},'',u);} $('mainNav').classList.remove('mobile-open'); if(view==='catalogo')renderCatalog();if(view==='favoritos')renderFavorites();if(view==='pedidos')renderOrders();if(view==='vender')renderSeller();if(view==='operacion')renderOperations();window.scrollTo({top:0,behavior:'smooth'}); }
function productImage(p){return (p.imagenes||[]).find(Boolean)||p.imagenUrl||placeholder(p.nombre||'Producto');}
function productImages(p){const arr=(p.imagenes||[]).filter(Boolean);if(!arr.length&&p.imagenUrl)arr.push(p.imagenUrl);return arr.length?arr:[placeholder(p.nombre||'Producto')];}
function renderStars(rating=0){const full=Math.round(Number(rating)||0);return `<span class="stars" aria-label="${full} de 5 estrellas">${'★'.repeat(Math.max(0,Math.min(5,full)))}${'☆'.repeat(5-Math.max(0,Math.min(5,full)))}</span>`;}
function categoryLabel(v='otros'){return ({hogar:'Hogar',electronica:'Electrónica',moda:'Moda',belleza:'Belleza',alimentos:'Alimentos',otros:'Otros'})[v]||v;}
function renderProductCard(p){const id=esc(p.id),image=esc(productImage(p)),fav=state.favorites.has(p.id),stock=Number(p.stock??p.existencia??0),rating=Number(p.ratingPromedio)||0;return `<article class="product-card" data-product="${id}"><div class="product-image-wrap" data-open-product="${id}">${image?`<img loading="lazy" src="${image}" alt="${esc(p.nombre)}" onerror="this.onerror=null;this.src='${placeholder(p.nombre)}'">`:`<div class="product-image-placeholder"><span class="material-symbols-outlined">inventory_2</span></div>`}<button class="favorite-toggle ${fav?'active':''}" data-favorite="${id}" aria-label="${fav?'Quitar de':'Agregar a'} favoritos"><span class="material-symbols-outlined">favorite</span></button>${p.destacado?'<span class="status-label">DESTACADO</span>':''}</div><div class="product-card-body"><span class="product-category">${esc(categoryLabel(p.categoria))}</span><h3 class="product-name" data-open-product="${id}">${esc(p.nombre)}</h3><div class="product-seller">${esc(p.vendedorNombre||p.tiendaNombre||'Vendedor local')}</div><div class="product-price-row"><span class="product-price">${money(p.precio)}</span></div><div class="rating-line">${renderStars(rating)} <span>${rating?rating.toFixed(1):'Nuevo'} ${p.totalResenas?`(${Number(p.totalResenas)})`:''}</span></div><div class="product-stock">${stock>0?`Disponible · ${stock} en existencia`:'Agotado'}</div></div><div class="product-card-actions"><button class="primary-btn" data-add-cart="${id}" ${stock<=0?'disabled':''}><span class="material-symbols-outlined">add_shopping_cart</span>Agregar</button><button class="secondary-btn" data-share-product="${id}" aria-label="Compartir"><span class="material-symbols-outlined">share</span></button></div></article>`;}
function renderHome(){const active=state.products.filter(p=>p.activo!==false&&Number(p.stock??p.existencia??0)>0);$('featuredProducts').innerHTML=active.slice().sort((a,b)=>(Number(b.ratingPromedio)||0)-(Number(a.ratingPromedio)||0)).slice(0,12).map(renderProductCard).join('')||'';$('latestProducts').innerHTML=active.slice().sort((a,b)=>timestamp(b.creadoEn)-timestamp(a.creadoEn)).slice(0,8).map(renderProductCard).join('');$('homeEmpty').classList.toggle('hidden',active.length>0);bindProductActions();}
function timestamp(v){if(v?.toMillis)return v.toMillis();if(v?.seconds)return v.seconds*1000;const d=new Date(v||0);return d.getTime()||0;}
function filteredProducts(){let arr=state.products.filter(p=>p.activo!==false);const q=state.search.trim().toLowerCase();if(q)arr=arr.filter(p=>[p.nombre,p.descripcion,p.vendedorNombre,p.tiendaNombre,p.categoria].some(v=>String(v||'').toLowerCase().includes(q)));const cat=$('categoryFilter')?.value||state.category;if(cat!=='todos')arr=arr.filter(p=>p.categoria===cat);const min=Number($('minPrice')?.value||0),max=Number($('maxPrice')?.value||0);arr=arr.filter(p=>Number(p.precio)>=min&&(!max||Number(p.precio)<=max));if($('inStockOnly')?.checked)arr=arr.filter(p=>Number(p.stock??p.existencia??0)>0);const sort=$('sortProducts')?.value||'relevance';if(sort==='newest')arr.sort((a,b)=>timestamp(b.creadoEn)-timestamp(a.creadoEn));if(sort==='priceAsc')arr.sort((a,b)=>Number(a.precio)-Number(b.precio));if(sort==='priceDesc')arr.sort((a,b)=>Number(b.precio)-Number(a.precio));if(sort==='rating')arr.sort((a,b)=>(Number(b.ratingPromedio)||0)-(Number(a.ratingPromedio)||0));return arr;}
function renderCatalog(){const arr=filteredProducts();$('catalogProducts').innerHTML=arr.map(renderProductCard).join('');$('catalogEmpty').classList.toggle('hidden',arr.length>0);$('catalogCount').textContent=`${arr.length} producto${arr.length===1?'':'s'} disponibles`;bindProductActions();}
function renderFavorites(){const arr=state.products.filter(p=>state.favorites.has(p.id)&&p.activo!==false);$('favoriteProducts').innerHTML=arr.map(renderProductCard).join('');$('favoritesEmpty').classList.toggle('hidden',arr.length>0);bindProductActions();}
function cartCount(){return state.cart.reduce((sum,x)=>sum+Number(x.cantidad||0),0)}
function cartSubtotal(){return state.cart.reduce((sum,x)=>sum+Number(x.precioSnapshot||x.precio||0)*Number(x.cantidad||0),0)}
function updateCartBadges(){ $('cartBadge').textContent=cartCount(); }
function addToCart(id){const p=state.products.find(x=>x.id===id);if(!p)return toast('Este producto ya no está disponible.','error');if(!state.user)return openAuthModal('Inicia sesión para agregar productos al carrito.');const stock=Number(p.stock??p.existencia??0);if(stock<=0)return toast('Este producto está agotado.','warning');let item=state.cart.find(x=>x.productoId===id);if(item){if(item.cantidad>=stock)return toast('No hay más existencia disponible.','warning');item.cantidad++;}else state.cart.push({productoId:id,nombre:p.nombre,precioSnapshot:Number(p.precio),cantidad:1,imagenes:productImages(p),vendedorId:p.vendedorId||p.propietarioId,vendedorNombre:p.vendedorNombre||p.tiendaNombre||'Vendedor local',stockSnapshot:stock});saveJSON('motiMpCart',state.cart);updateCartBadges();toast('Producto agregado al carrito.');}
function toggleFavorite(id){if(state.favorites.has(id))state.favorites.delete(id);else state.favorites.add(id);saveJSON('motiMpFavorites',[...state.favorites]);if(state.user){setDoc(doc(db,'marketplaceFavoritos',state.user.uid,'items',id),{productoId:id,usuarioId:state.user.uid,actualizadoEn:serverTimestamp()},{merge:true}).catch(()=>{});if(!state.favorites.has(id))deleteDoc(doc(db,'marketplaceFavoritos',state.user.uid,'items',id)).catch(()=>{});}renderHome();if(state.view==='catalogo')renderCatalog();if(state.view==='favoritos')renderFavorites();}
async function shareProduct(id){const p=state.products.find(x=>x.id===id);if(!p)return;const url=new URL(location.href);url.search='';url.searchParams.set('producto',id);const data={title:p.nombre,text:`${p.nombre} · ${money(p.precio)} en MOTI GO Marketplace`,url:url.toString()};try{if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(`${data.text}\n${data.url}`);toast('Enlace del producto copiado.');}}catch(e){if(e.name!=='AbortError')toast('No se pudo compartir. Copia el enlace de la barra del navegador.','warning');}}
function bindProductActions(root=document){root.querySelectorAll('[data-add-cart]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',e=>{e.stopPropagation();addToCart(b.dataset.addCart);});});root.querySelectorAll('[data-favorite]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',e=>{e.stopPropagation();toggleFavorite(b.dataset.favorite);});});root.querySelectorAll('[data-share-product]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',e=>{e.stopPropagation();shareProduct(b.dataset.shareProduct);});});root.querySelectorAll('[data-open-product]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',()=>openProduct(b.dataset.openProduct));});}
function openProduct(id){const p=state.products.find(x=>x.id===id);if(!p)return;const images=productImages(p);let ix=0;openModal(`<div class="product-detail"><div class="detail-gallery"><div class="detail-main-image"><img id="detailMainImage" src="${esc(images[0])}" alt="${esc(p.nombre)}">${images.length>1?`<button class="gallery-arrow left" id="detailPrev"><span class="material-symbols-outlined">chevron_left</span></button><button class="gallery-arrow right" id="detailNext"><span class="material-symbols-outlined">chevron_right</span></button>`:''}</div><div class="detail-thumbs" id="detailThumbs">${images.map((im,i)=>`<button class="${i===0?'active':''}" data-thumb="${i}"><img src="${esc(im)}" alt="Vista ${i+1}"></button>`).join('')}</div></div><div class="detail-info"><span class="product-category">${esc(categoryLabel(p.categoria))}</span><h2>${esc(p.nombre)}</h2><div class="rating-line">${renderStars(p.ratingPromedio)} <span>${Number(p.ratingPromedio)?Number(p.ratingPromedio).toFixed(1):'Sin valoraciones'} · ${Number(p.totalResenas)||0} opiniones</span></div><div class="detail-price">${money(p.precio)}</div><div class="detail-meta"><span>${Number(p.stock??p.existencia)>0?'Disponible':'Agotado'}</span><span>Vendedor: ${esc(p.vendedorNombre||p.tiendaNombre||'Vendedor local')}</span></div><p class="detail-description">${esc(p.descripcion||'El vendedor no agregó una descripción.')}</p><div class="notice-inline">Entrega estimada: de 1 a 3 días desde la compra en zona habilitada; puede ser de hasta 4 días en comunidades con mayor recorrido. La fecha se confirma cuando los productos estén listos.</div><div class="detail-actions"><button class="primary-btn" id="detailAdd" ${Number(p.stock??p.existencia)<=0?'disabled':''}><span class="material-symbols-outlined">add_shopping_cart</span>Agregar al carrito</button><button class="secondary-btn" id="detailFav"><span class="material-symbols-outlined">favorite</span></button><button class="secondary-btn" id="detailShare"><span class="material-symbols-outlined">share</span></button></div><div class="detail-seller"><b>Compra con seguimiento</b><br>Los productos se identifican al llegar al almacén y se agrupan para la entrega o recolección por el cliente.</div></div></div><div class="reviews"><h3>Opiniones de compradores</h3><div id="reviewList"><p class="muted small">Cargando opiniones…</p></div><div id="writeReviewArea"></div></div>`,true);
const updateImage=(n)=>{ix=(n+images.length)%images.length;$('detailMainImage').src=images[ix];$('detailThumbs')?.querySelectorAll('button').forEach((b,i)=>b.classList.toggle('active',i===ix));};$('detailPrev')?.addEventListener('click',()=>updateImage(ix-1));$('detailNext')?.addEventListener('click',()=>updateImage(ix+1));$('detailThumbs')?.querySelectorAll('[data-thumb]').forEach(b=>b.addEventListener('click',()=>updateImage(Number(b.dataset.thumb))));$('detailAdd')?.addEventListener('click',()=>{addToCart(id);});$('detailFav')?.addEventListener('click',()=>toggleFavorite(id));$('detailShare')?.addEventListener('click',()=>shareProduct(id));loadReviews(p);}
async function loadReviews(p){const list=$('reviewList'),area=$('writeReviewArea');if(!list)return;try{const snap=await getDocs(query(collection(db,'marketplaceResenas'),where('productoId','==',p.id),limit(30)));list.innerHTML=snap.empty?'<p class="muted small">Todavía no hay opiniones. Después de una compra entregada podrás dejar la primera valoración.</p>':snap.docs.map(d=>{const r=d.data();return `<div class="review-item"><b>${esc(r.clienteNombre||'Comprador')}</b> <span class="stars">${'★'.repeat(Math.max(0,Math.min(5,Number(r.calificacion)||0)))}</span><p>${esc(r.comentario||'')}</p><small class="muted">${fmtDate(r.creadoEn)}</small></div>`;}).join('');}catch(e){list.innerHTML='<p class="muted small">Las opiniones estarán disponibles cuando se habiliten las reglas de Marketplace.</p>';}
if(!state.user){area.innerHTML='<button class="secondary-btn" id="reviewLogin">Inicia sesión para valorar</button>';area.querySelector('button')?.addEventListener('click',()=>openAuthModal('Inicia sesión para escribir una opinión.'));return;}
let delivered=[];try{const q=await getDocs(query(collection(db,'marketplacePedidos'),where('clienteId','==',state.user.uid),limit(50)));const candidates=q.docs.map(d=>({id:d.id,...d.data()})).filter(o=>['entregado','recogido_cliente'].includes(o.estado)&&(o.items||[]).some(i=>i.productoId===p.id));delivered=[];for(const o of candidates){const reviewSnap=await getDoc(doc(db,'marketplaceResenas',`${o.id}_${p.id}`));if(!reviewSnap.exists())delivered.push(o);}}catch{}
if(delivered.length){area.innerHTML=`<div class="review-write"><h3>Valora tu compra</h3><form id="reviewForm"><div class="rating-input" id="ratingInput">${[1,2,3,4,5].map(n=>`<button type="button" data-rating="${n}" class="${n<=state.selectedRating?'active':''}" aria-label="${n} estrellas">★</button>`).join('')}</div><label class="form-field"><span>Tu opinión</span><textarea id="reviewComment" maxlength="1200" required placeholder="¿Qué te pareció el producto y la experiencia de compra?"></textarea></label><label class="form-field"><span>Pedido</span><select id="reviewOrder">${delivered.map(o=>`<option value="${esc(o.id)}">${esc(o.folio||o.id)}</option>`).join('')}</select></label><button class="primary-btn" type="submit">Publicar opinión</button></form></div>`;area.querySelectorAll('[data-rating]').forEach(b=>b.addEventListener('click',()=>{state.selectedRating=Number(b.dataset.rating);area.querySelectorAll('[data-rating]').forEach(x=>x.classList.toggle('active',Number(x.dataset.rating)<=state.selectedRating));}));$('reviewForm').addEventListener('submit',async e=>{e.preventDefault();const orderId=$('reviewOrder').value;try{await setDoc(doc(db,'marketplaceResenas',`${orderId}_${p.id}`),{productoId:p.id,productoNombre:p.nombre,clienteId:state.user.uid,clienteNombre:state.profile?.nombre||state.user.displayName||'Comprador',pedidoId:orderId,calificacion:state.selectedRating,comentario:$('reviewComment').value.trim(),creadoEn:serverTimestamp()});toast('Gracias por compartir tu opinión.');loadReviews(p);}catch(err){toast('No se pudo publicar la opinión: '+friendlyError(err),'error');}});}else{area.innerHTML='<p class="muted small">Solo puedes valorar un producto después de que un pedido que lo incluya se haya entregado o recogido.</p>';}}
function openCart(){renderCart();$('cartDrawer').classList.remove('hidden');}
function closeCart(){$('cartDrawer').classList.add('hidden');}
function renderCart(){const host=$('cartItems');const sellerCount=new Set(state.cart.map(x=>x.vendedorId).filter(Boolean)).size;const multiSeller=sellerCount>1;$('cartPaymentNotice').classList.toggle('hidden',!multiSeller);$('cartPaymentNotice').textContent=multiSeller?'Tu carrito tiene varias tiendas. El pago único multitienda se activará cuando Mercado Pago autorice e integremos Split 1:N. Por seguridad, el checkout está temporalmente bloqueado; no se cobrará el pedido.':'';if(!state.cart.length){host.innerHTML='<div class="empty-state"><span class="material-symbols-outlined">shopping_cart</span><h3>Tu carrito está vacío</h3><p>Agrega productos de una o varias tiendas. Se consolidarán en un solo pedido.</p><button class="primary-btn" data-close-cart>Explorar productos</button></div>';$('cartSubtotal').textContent=money(0);$('cartShipping').textContent='Se calcula al confirmar';$('checkoutBtn').disabled=true;host.querySelector('[data-close-cart]')?.addEventListener('click',closeCart);return;}$('checkoutBtn').disabled=multiSeller;host.innerHTML=state.cart.map(item=>`<div class="cart-line"><img src="${esc(item.imagenes?.[0]||placeholder(item.nombre))}" alt="${esc(item.nombre)}"><div class="cart-line-main"><b>${esc(item.nombre)}</b><small>${esc(item.vendedorNombre||'Vendedor local')}</small><div class="cart-line-bottom"><b>${money(Number(item.precioSnapshot||item.precio)*item.cantidad)}</b><div class="quantity-control"><button data-qty="-1" data-id="${esc(item.productoId)}">−</button><b>${item.cantidad}</b><button data-qty="1" data-id="${esc(item.productoId)}">+</button><button class="icon-btn" data-remove-cart="${esc(item.productoId)}" title="Quitar"><span class="material-symbols-outlined">delete</span></button></div></div></div></div>`).join('');host.querySelectorAll('[data-qty]').forEach(b=>b.addEventListener('click',()=>changeCartQty(b.dataset.id,Number(b.dataset.qty))));host.querySelectorAll('[data-remove-cart]').forEach(b=>b.addEventListener('click',()=>removeCart(b.dataset.removeCart)));$('cartSubtotal').textContent=money(cartSubtotal());$('cartShipping').textContent='Se confirma con la ruta';}
function changeCartQty(id,delta){const item=state.cart.find(x=>x.productoId===id);if(!item)return;const p=state.products.find(x=>x.id===id);const max=Number(p?.stock??item.stockSnapshot??99);item.cantidad=Math.max(0,Math.min(max,item.cantidad+delta));if(!item.cantidad)state.cart=state.cart.filter(x=>x.productoId!==id);saveJSON('motiMpCart',state.cart);updateCartBadges();renderCart();}
function removeCart(id){state.cart=state.cart.filter(x=>x.productoId!==id);saveJSON('motiMpCart',state.cart);updateCartBadges();renderCart();}
function openCheckout(){if(!state.user)return openAuthModal('Inicia sesión para completar la compra.');if(new Set(state.cart.map(x=>x.vendedorId).filter(Boolean)).size>1)return toast('El checkout multitienda está bloqueado hasta habilitar Split 1:N de Mercado Pago. No se realizó ningún cobro.','warning');if(!state.cart.length)return toast('Agrega productos antes de continuar.','warning');closeCart();const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);const maxDate=new Date();maxDate.setDate(maxDate.getDate()+4);openModal(`<form id="checkoutForm" class="modal-form"><h2>Confirmar compra</h2><p>Un solo pago para tu carrito multitienda. Los productos se reúnen en el almacén antes de programar la entrega.</p><div class="form-grid"><label class="form-field"><span>Nombre de quien recibe</span><input name="nombreRecibe" required maxlength="100" value="${esc(state.profile?.nombre||state.user.displayName||'')}"></label><label class="form-field"><span>Teléfono de contacto</span><input name="telefono" required inputmode="tel" maxlength="20" value="${esc(state.profile?.telefono||'')}"></label><label class="form-field full-span"><span>¿Cómo quieres recibir tu compra?</span><select name="modoEntrega" id="modoEntrega"><option value="domicilio">Entrega a domicilio por MOTI GO</option><option value="almacen">Recoger en almacén cuando esté listo</option></select></label><label class="form-field full-span" id="addressField"><span>Dirección y comunidad dentro de Ostuacán</span><input name="direccion" id="checkoutAddress" required maxlength="240" placeholder="Calle, barrio, comunidad o referencia"><button type="button" class="secondary-btn" id="useMyLocation">Usar mi ubicación GPS</button><span id="locationStatus" class="form-hint">Opcional; ayuda a organizar la ruta. El destino debe estar dentro de una zona autorizada.</span><input type="hidden" name="destinoLat" id="destinoLat"><input type="hidden" name="destinoLng" id="destinoLng"></label><label class="form-field full-span" id="referenceField"><span>Referencias para llegar</span><input name="referencias" maxlength="240" placeholder="Color de casa, punto conocido, etc."></label><label class="form-field" id="zoneField"><span>Comunidad / zona</span><input name="zona" id="checkoutZone" required maxlength="100" placeholder="Ej. Cabecera municipal"></label><label class="form-field"><span>Fecha preferida (opcional)</span><input name="fechaPreferida" type="date" min="${tomorrow.toISOString().slice(0,10)}" max="${maxDate.toISOString().slice(0,10)}"></label><label class="form-field full-span"><span>Notas para el pedido (opcional)</span><textarea name="notas" maxlength="500" placeholder="Instrucciones adicionales"></textarea></label></div><div class="notice-inline" style="margin-top:14px">Entrega estimada: desde mañana y normalmente dentro de 3 días; en zonas con mayor recorrido puede tomar hasta 4 días. Se confirma según disponibilidad de los vendedores y la ruta. El pago no se marca como aprobado hasta verificarlo con Mercado Pago.</div><div id="checkoutError" class="error-inline"></div><div class="form-actions"><button type="button" class="secondary-btn" data-close-modal>Cancelar</button><button type="submit" id="payNowBtn" class="primary-btn"><span class="material-symbols-outlined">lock</span>Continuar a pago seguro</button></div></form>`);$('modoEntrega').addEventListener('change',()=>{const pickup=$('modoEntrega').value==='almacen';$('addressField').classList.toggle('hidden',pickup);$('referenceField').classList.toggle('hidden',pickup);$('checkoutAddress').required=!pickup;$('zoneField').classList.toggle('hidden',pickup);$('checkoutZone').required=!pickup;if(pickup)$('checkoutZone').value='Almacén central';else if($('checkoutZone').value==='Almacén central')$('checkoutZone').value='';});$('useMyLocation')?.addEventListener('click',()=>{if(!navigator.geolocation)return $('locationStatus').textContent='Este navegador no permite obtener ubicación.';$('locationStatus').textContent='Obteniendo ubicación…';navigator.geolocation.getCurrentPosition(pos=>{$('destinoLat').value=pos.coords.latitude;$('destinoLng').value=pos.coords.longitude;$('locationStatus').textContent='Ubicación guardada. Escribe también tu dirección o referencia.';},()=>{$('locationStatus').textContent='No se pudo obtener la ubicación. Puedes escribir la dirección manualmente.';},{enableHighAccuracy:true,timeout:12000,maximumAge:60000});});$('checkoutForm').addEventListener('submit',submitCheckout);loadCheckoutZones();}
async function loadCheckoutZones(){try{const snap=await getDoc(doc(db,'marketplaceConfig','operacion'));const select=$('checkoutZone');if(!select)return;const c=snap.exists()?snap.data():null;const zones=(c?.zonasPermitidas||[]);select.innerHTML='<option value="">Selecciona tu zona</option>'+zones.map(z=>`<option value="${esc(z)}">${esc(z)}</option>`).join('');if(!zones.length)select.innerHTML='<option value="">Cobertura aún no configurada</option>'; }catch(e){const select=$('checkoutZone');if(select)select.innerHTML='<option value="">No se pudo cargar la cobertura</option>';}}
async function submitCheckout(e){e.preventDefault();const form=e.currentTarget,button=$('payNowBtn');setBusy(button,true,'Preparando pago…');$('checkoutError').textContent='';const fd=new FormData(form);const mode=fd.get('modoEntrega');if(mode==='domicilio'&&!String(fd.get('direccion')||'').trim()){setBusy(button,false);return $('checkoutError').textContent='Escribe la dirección de entrega.';}const items=state.cart.map(x=>({productoId:x.productoId,cantidad:Number(x.cantidad)}));try{const res=await callCreateCheckout({items,modoEntrega:mode,nombreRecibe:String(fd.get('nombreRecibe')||'').trim(),telefono:String(fd.get('telefono')||'').trim(),direccion:String(fd.get('direccion')||'').trim(),referencias:String(fd.get('referencias')||'').trim(),zona:String(fd.get('zona')||'').trim(),fechaPreferida:String(fd.get('fechaPreferida')||''),notas:String(fd.get('notas')||'').trim(),destinoLat:fd.get('destinoLat')?Number(fd.get('destinoLat')):null,destinoLng:fd.get('destinoLng')?Number(fd.get('destinoLng')):null,municipio:'Ostuacán',estado:'Chiapas'});const data=res.data||{};if(data.checkoutUrl){saveJSON('motiMpPendingCheckout',{pedidoId:data.pedidoId,folio:data.folio,createdAt:Date.now()});location.href=data.checkoutUrl;return;}throw new Error(data.message||'No se recibió el enlace de pago seguro.');}catch(err){$('checkoutError').textContent=friendlyError(err);setBusy(button,false);}}
function openAuthModal(message='Inicia sesión o crea tu cuenta para comprar y vender.'){openModal(`<div class="modal-form"><h2>Bienvenido a MOTI GO</h2><p>${esc(message)}</p><div class="form-grid"><label class="form-field full-span"><span>Correo electrónico</span><input id="authEmail" type="email" required autocomplete="email" placeholder="tu@correo.com"></label><label class="form-field full-span"><span>Contraseña</span><input id="authPassword" type="password" required minlength="6" autocomplete="current-password" placeholder="Mínimo 6 caracteres"></label><label class="form-field full-span" id="authNameField"><span>Nombre (para crear cuenta)</span><input id="authName" maxlength="100" placeholder="Tu nombre"></label></div><div id="authError" class="error-inline"></div><div class="form-actions"><button class="secondary-btn" id="switchToLogin" type="button">Ya tengo cuenta</button><button class="primary-btn" id="authSubmit" type="button">Crear cuenta</button></div><p class="small muted" style="margin-top:15px">La cuenta de inicio de sesión se comparte con MOTI GO, pero Marketplace usa colecciones y permisos separados.</p></div>`);let create=true;const btn=$('authSubmit'),switchBtn=$('switchToLogin'),nameField=$('authNameField');const updateMode=()=>{btn.textContent=create?'Crear cuenta':'Iniciar sesión';switchBtn.textContent=create?'Ya tengo cuenta':'Crear cuenta nueva';nameField.classList.toggle('hidden',!create);$('authPassword').autocomplete=create?'new-password':'current-password';};switchBtn.addEventListener('click',()=>{create=!create;updateMode();});btn.addEventListener('click',async()=>{const email=$('authEmail').value.trim(),password=$('authPassword').value,name=$('authName').value.trim();if(!email||!password)return $('authError').textContent='Escribe tu correo y contraseña.';if(create&&!name)return $('authError').textContent='Escribe tu nombre.';setBusy(btn,true,create?'Creando…':'Ingresando…');try{if(create){const cred=await createUserWithEmailAndPassword(auth,email,password);await updateProfile(cred.user,{displayName:name});await setDoc(doc(db,'marketplacePerfiles',cred.user.uid),{uid:cred.user.uid,nombre:name,email:cred.user.email,rol:'vendedor',activo:true,metodoAbastecimiento:'recoleccion_motigo',creadoEn:serverTimestamp(),actualizadoEn:serverTimestamp()},{merge:true});}else await signInWithEmailAndPassword(auth,email,password);closeModal();toast(create?'Cuenta creada. Ya puedes comprar y publicar productos.':'Sesión iniciada.');}catch(err){$('authError').textContent=friendlyError(err);}finally{setBusy(btn,false);}});updateMode();}
function friendlyError(err){const code=err?.code||'';if(code.includes('permission-denied'))return 'Firebase rechazó esta operación. Verifica que el fragmento de reglas de Marketplace esté agregado correctamente.';if(code.includes('unauthenticated'))return 'Tu sesión expiró. Inicia sesión de nuevo.';if(code.includes('functions/not-found')||code.includes('not-found'))return 'El backend de pagos aún no está desplegado. La compra no se marcó como pagada. Sigue LEEME-INSTALACION.txt para configurar las funciones.';if(code.includes('functions/failed-precondition'))return err.message||'Falta configurar el pago seguro o el vendedor aún no vinculó Mercado Pago.';if(code.includes('functions/unavailable'))return 'El servicio de pago no está disponible ahora. Intenta de nuevo más tarde.';if(code.includes('auth/email-already-in-use'))return 'Ese correo ya tiene cuenta. Usa Iniciar sesión.';if(code.includes('auth/invalid-credential')||code.includes('auth/wrong-password'))return 'Correo o contraseña incorrectos.';if(code.includes('auth/weak-password'))return 'La contraseña debe tener al menos 6 caracteres.';return err?.message||'Ocurrió un error inesperado.';}
function renderOrders(){if(!state.user){$('ordersList').innerHTML='';$('ordersEmpty').classList.remove('hidden');$('ordersEmpty').querySelector('h3').textContent='Inicia sesión para ver tus pedidos';$('ordersEmpty').querySelector('p').textContent='El seguimiento está ligado a tu cuenta.';return;}const arr=state.orders;$('ordersEmpty').classList.toggle('hidden',arr.length>0);$('ordersList').innerHTML=arr.map(o=>{const status=statusLabels[o.estado]||o.estado||'En proceso';const warning=['incidencia','reembolso_pendiente','cancelacion_solicitada'].includes(o.estado);const items=(o.items||[]).slice(0,4);return `<article class="order-card"><div class="order-card-header"><div><div class="order-number">Pedido ${esc(o.folio||o.id)}</div><div class="order-date">Compra: ${fmtDate(o.creadoEn)} · ${o.modoEntrega==='almacen'?'Recoger en almacén':'Entrega a domicilio'}</div></div><span class="status-pill ${warning?'warning':''}">${esc(status)}</span></div><div class="timeline">${['pagado','esperando_vendedores','recibido_almacen','programado','en_reparto','entregado'].slice(0,4).map((s,i)=>`<div class="timeline-step ${statusProgress(o.estado)>=i+1?'done':''}">${esc(statusLabels[s])}</div>`).join('')}</div><div class="order-items-preview">${items.map(i=>`<span class="order-item-chip">${esc(i.nombre)} × ${Number(i.cantidad)||1}</span>`).join('')}${(o.items||[]).length>4?`<span class="order-item-chip">+${o.items.length-4} más</span>`:''}</div><div class="order-footer"><div><div class="small muted">Total pagado / por pagar</div><div class="order-total">${money(o.total)}</div><div class="small muted">${o.fechaEstimadaDesde?`Estimado: ${fmtDate(o.fechaEstimadaDesde)} – ${fmtDate(o.fechaEstimadaHasta)}`:'Fecha estimada: en cálculo'}</div></div><div class="order-actions"><button class="secondary-btn" data-order-detail="${esc(o.id)}">Ver detalle</button>${o.estado==='entregado'||o.estado==='recogido_cliente'?'':`<button class="secondary-btn" data-order-help="${esc(o.id)}">Tengo un problema</button>`}</div></div></article>`;}).join('');$('ordersList').querySelectorAll('[data-order-detail]').forEach(b=>b.addEventListener('click',()=>openOrderDetail(b.dataset.orderDetail)));$('ordersList').querySelectorAll('[data-order-help]').forEach(b=>b.addEventListener('click',()=>requestOrderHelp(b.dataset.orderHelp)));}
function statusProgress(s){const map={pendiente_pago:0,pagado:1,esperando_vendedores:1,recepcion_parcial:2,recibido_almacen:3,listo_para_ruta:3,programado:4,en_reparto:5,entregado:6,recogido_cliente:6};return map[s]||0;}
function openOrderDetail(id){const o=state.orders.find(x=>x.id===id);if(!o)return;openModal(`<div class="modal-form"><span class="eyebrow green">SEGUIMIENTO</span><h2>Pedido ${esc(o.folio||o.id)}</h2><p>Estado actual: <b>${esc(statusLabels[o.estado]||o.estado)}</b></p><div class="order-items-preview">${(o.items||[]).map(i=>`<span class="order-item-chip">${esc(i.nombre)} × ${Number(i.cantidad)||1} · ${money(i.precioSnapshot||i.precio)}</span>`).join('')}</div><div class="panel-card"><b>Recepción y entrega</b><p class="muted small">${o.modoEntrega==='almacen'?'Recogerás en el almacén cuando el pedido completo esté listo.':'MOTI GO reunirá los productos y programará la entrega en una ruta.'}</p><p class="small">Fecha estimada: ${o.fechaEstimadaDesde?`${fmtDate(o.fechaEstimadaDesde)} a ${fmtDate(o.fechaEstimadaHasta)}`:'pendiente de confirmación'}</p><p class="small">Pago: ${esc(o.pagoEstado||'pendiente')}</p>${['en_reparto','listo_para_recoger','programado'].includes(o.estado)?`<p class="small"><b>Código de entrega/recogida: ${esc(o.codigoEntrega||'Se generará al confirmar el pedido')}</b><br>Compártelo solo al recibir el producto.</p>`:''}</div><div class="form-actions"><button class="secondary-btn" data-close-modal>Cerrar</button></div></div>`);}
async function requestOrderHelp(id){if(!state.user)return;const reason=prompt('Describe brevemente el problema del pedido:');if(!reason?.trim())return;try{await addDoc(collection(db,'marketplaceIncidencias'),{pedidoId:id,clienteId:state.user.uid,tipo:'consulta_cliente',descripcion:reason.trim(),estado:'abierta',creadoEn:serverTimestamp()});toast('Se registró tu solicitud. El equipo de Marketplace podrá revisarla.');}catch(e){toast(friendlyError(e),'error');}}
function renderSeller(){if(!state.user){$('sellerLoginNotice').classList.remove('hidden');$('sellerWorkspace').classList.add('hidden');return;}$('sellerLoginNotice').classList.add('hidden');$('sellerWorkspace').classList.remove('hidden');const mine=state.sellerProducts;$('sellerStats').innerHTML=`<div class="stat-card"><span>Productos publicados</span><b>${mine.length}</b></div><div class="stat-card"><span>Solicitudes recibidas</span><b>${state.sellerRequests.length}</b></div><div class="stat-card"><span>En preparación</span><b>${state.sellerRequests.filter(r=>r.estado==='pendiente_preparacion'||r.estado==='en_preparacion').length}</b></div>`;$('sellerProducts').innerHTML=mine.map(p=>`<div class="seller-list-item"><img src="${esc(productImage(p))}" alt=""><div><b>${esc(p.nombre)}</b><small>${money(p.precio)} · Stock ${Number(p.stock??0)} · ${p.activo===false?'Pausado':'Publicado'}</small></div><button class="secondary-btn" data-toggle-product="${esc(p.id)}">${p.activo===false?'Activar':'Pausar'}</button><button class="secondary-btn" data-edit-product="${esc(p.id)}">Editar</button></div>`).join('')||'<p class="muted small">Todavía no has publicado productos.</p>';$('sellerRequests').innerHTML=state.sellerRequests.map(r=>`<div class="seller-list-item"><div><b>Pedido ${esc(r.folio||r.pedidoId||r.id)}</b><small>${esc(r.productosResumen||'Productos de tu tienda')} · ${esc(statusLabels[r.estado]||r.estado)}</small><small>Entrega estimada: ${r.fechaEstimadaDesde?fmtDate(r.fechaEstimadaDesde):'por confirmar'}</small></div><button class="secondary-btn" data-print-request-label="${esc(r.id)}">Imprimir etiqueta</button>${['pendiente_preparacion','en_preparacion'].includes(r.estado)?`<button class="primary-btn" data-request-ready="${esc(r.id)}">Marcar preparado</button>`:''}</div>`).join('')||'<p class="muted small">Cuando alguien compre tus productos, la solicitud aparecerá aquí.</p>';$('sellerProducts').querySelectorAll('[data-toggle-product]').forEach(b=>b.addEventListener('click',()=>toggleProduct(b.dataset.toggleProduct)));$('sellerProducts').querySelectorAll('[data-edit-product]').forEach(b=>b.addEventListener('click',()=>openProductForm(state.products.find(p=>p.id===b.dataset.editProduct))));$('sellerRequests').querySelectorAll('[data-request-ready]').forEach(b=>b.addEventListener('click',()=>markRequestReady(b.dataset.requestReady,b)));$('sellerRequests').querySelectorAll('[data-print-request-label]').forEach(b=>b.addEventListener('click',()=>printRequestLabel(b.dataset.printRequestLabel)));}
function openProductForm(product=null){if(!state.user)return openAuthModal('Inicia sesión para publicar productos.');const p=product||{};openModal(`<form id="productForm" class="modal-form"><h2>${product?'Editar producto':'Publicar un producto'}</h2><p>Se permite publicar desde una sola pieza. Usa fotos claras, precio real y existencia disponible. Los artículos deben poder recibirse y entregarse en la cobertura de Marketplace.</p><div class="form-grid"><label class="form-field full-span"><span>Nombre del producto *</span><input name="nombre" required maxlength="120" value="${esc(p.nombre||'')}"></label><label class="form-field"><span>Categoría *</span><select name="categoria" required>${['hogar','electronica','moda','belleza','alimentos','otros'].map(c=>`<option value="${c}" ${p.categoria===c?'selected':''}>${categoryLabel(c)}</option>`).join('')}</select></label><label class="form-field"><span>Precio (MXN) *</span><input name="precio" type="number" required min="1" max="1000000" step="0.01" value="${esc(p.precio??'')}"></label><label class="form-field"><span>Existencia *</span><input name="stock" type="number" required min="0" max="100000" step="1" value="${esc(p.stock??1)}"></label><label class="form-field"><span>Condición</span><select name="condicion"><option value="nuevo" ${p.condicion==='nuevo'?'selected':''}>Nuevo</option><option value="usado" ${p.condicion==='usado'?'selected':''}>Usado</option><option value="artesanal" ${p.condicion==='artesanal'?'selected':''}>Hecho a mano / artesanal</option></select></label><label class="form-field full-span"><span>Descripción *</span><textarea name="descripcion" required maxlength="3000">${esc(p.descripcion||'')}</textarea></label><label class="form-field full-span"><span>Fotografías del producto (hasta 8)</span><input name="imagenes" id="productImagesInput" type="file" accept="image/jpeg,image/png,image/webp" multiple ${product?'':'required'}><span class="form-hint">JPG, PNG o WebP. Máximo 5 MB por foto. Las fotos se guardan en una ruta separada de Storage.</span></label></div><div id="productUploadProgress" class="small muted"></div><div id="productFormError" class="error-inline"></div><div class="form-actions"><button type="button" class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" type="submit" id="saveProductBtn">${product?'Guardar cambios':'Publicar producto'}</button></div></form>`);$('productForm').addEventListener('submit',e=>saveProduct(e,product));}
async function saveProduct(e,existing){e.preventDefault();const form=e.currentTarget,btn=$('saveProductBtn'),fd=new FormData(form);const nombre=String(fd.get('nombre')||'').trim(),precio=Number(fd.get('precio')),stock=Number(fd.get('stock'));if(!nombre||precio<=0||stock<0)return $('productFormError').textContent='Revisa nombre, precio y existencia.';setBusy(btn,true,'Guardando…');$('productFormError').textContent='';try{const profile=state.profile||{};let images=existing?productImages(existing).filter(x=>!x.startsWith('data:image/svg+xml')):[];const files=[...($('productImagesInput').files||[])];if(files.length>8)throw new Error('Puedes subir hasta 8 fotografías.');for(let i=0;i<files.length;i++){const file=files[i];if(file.size>5*1024*1024)throw new Error(`La foto ${file.name} supera 5 MB.`);if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Usa imágenes JPG, PNG o WebP.');const path=`marketplace-productos/${state.user.uid}/${Date.now()}_${i}_${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const task=uploadBytesResumable(storageRef(storage,path),file,{contentType:file.type});await new Promise((resolve,reject)=>task.on('state_changed',s=>{$('productUploadProgress').textContent=`Subiendo fotografías: ${Math.round(100*s.bytesTransferred/s.totalBytes)}%`;},reject,async()=>{try{images.push(await getDownloadURL(task.snapshot.ref));resolve();}catch(err){reject(err);}}));}if(!images.length)throw new Error('Agrega por lo menos una fotografía.');const data={nombre,categoria:String(fd.get('categoria')),precio,stock,existencia:stock,descripcion:String(fd.get('descripcion')||'').trim(),condicion:String(fd.get('condicion')||'nuevo'),imagenes:images,imagenUrl:images[0],vendedorId:state.user.uid,propietarioId:state.user.uid,vendedorNombre:profile.nombre||state.user.displayName||state.user.email,tiendaNombre:profile.tiendaNombre||profile.nombre||state.user.displayName||'Vendedor local',metodoAbastecimiento:profile.metodoAbastecimiento||'recoleccion_motigo',activo:existing?existing.activo!==false:true,actualizadoEn:serverTimestamp()};if(existing){await updateDoc(doc(db,'marketplaceProductos',existing.id),data);}else{data.creadoEn=serverTimestamp();data.ratingPromedio=0;data.totalResenas=0;await addDoc(collection(db,'marketplaceProductos'),data);}closeModal();toast(existing?'Producto actualizado.':'Producto publicado.');}catch(err){$('productFormError').textContent=friendlyError(err);}finally{setBusy(btn,false);}}
async function toggleProduct(id){const p=state.sellerProducts.find(x=>x.id===id);if(!p||p.vendedorId!==state.user?.uid)return;try{await updateDoc(doc(db,'marketplaceProductos',id),{activo:p.activo===false,actualizadoEn:serverTimestamp()});toast(p.activo===false?'Producto activado.':'Producto pausado.');}catch(e){toast(friendlyError(e),'error');}}
async function markRequestReady(id,button){setBusy(button,true,'Guardando…');try{await updateDoc(doc(db,'marketplaceSolicitudesTienda',id),{estado:'preparado',preparadoEn:serverTimestamp(),actualizadoEn:serverTimestamp()});toast('Marcado como preparado. MOTI GO puede coordinar la recolección.');}catch(e){toast(friendlyError(e),'error');}finally{setBusy(button,false);}}
function setupOpsSubscriptions(){if(state.opsRequestUnsub){state.opsRequestUnsub();state.opsRequestUnsub=null;}if(state.opsRouteUnsub){state.opsRouteUnsub();state.opsRouteUnsub=null;}if(!state.user||!state.role?.activo||!['admin','almacen','repartidor'].includes(state.role.rol))return;if(['admin','almacen'].includes(state.role.rol)){state.opsRequestUnsub=onSnapshot(query(collection(db,'marketplaceSolicitudesTienda'),limit(200)),snap=>{state.allRequests=snap.docs.map(d=>({id:d.id,...d.data()}));if(state.view==='operacion')renderOperations();},err=>console.warn('Solicitudes operativas',err));}if(['admin','almacen','repartidor'].includes(state.role.rol)){const q=state.role.rol==='repartidor'?query(collection(db,'marketplaceRutas'),where('repartidorId','==',state.user.uid),limit(100)):query(collection(db,'marketplaceRutas'),limit(100));state.opsRouteUnsub=onSnapshot(q,snap=>{state.opsRoutes=snap.docs.map(d=>({id:d.id,...d.data()}));if(state.view==='operacion')renderOperations();},err=>console.warn('Rutas operativas',err));}}
function renderOperations(){const allowed=state.user&&state.role?.activo===true&&['admin','almacen','repartidor'].includes(state.role?.rol);$('operationAccessDenied').classList.toggle('hidden',!!allowed);$('operationWorkspace').classList.toggle('hidden',!allowed);$('operationNav').classList.toggle('hidden',!allowed);if(!allowed)return;document.querySelectorAll('[data-op-tab]').forEach(b=>b.classList.toggle('active',b.dataset.opTab===state.opTab));document.querySelectorAll('.op-panel').forEach(p=>p.classList.toggle('hidden',p.id!==`op-${state.opTab}`));renderOpsData();}
async function renderOpsData(){if(!state.user||!state.role)return;try{if(['admin','almacen'].includes(state.role.rol)){const req=state.allRequests;$('warehouseOrders').innerHTML=req.map(r=>`<div class="ops-card"><div class="ops-card-header"><div><b>Solicitud ${esc(r.folio||r.id)}</b><p>${esc(r.productosResumen||'Productos de vendedor')} · Vendedor: ${esc(r.vendedorNombre||r.vendedorId||'')}</p><p>Estado: ${esc(statusLabels[r.estado]||r.estado)} · ${r.direccionVendedor?esc(r.direccionVendedor):''}</p></div><span class="status-pill">${esc(r.estado)}</span></div><div class="ops-actions">${['preparado','en_recoleccion','recogido_por_motigo','recibido_almacen'].includes(r.estado)?`<button class="primary-btn" data-receive-request="${esc(r.id)}">Confirmar recepción</button>`:''}<button class="secondary-btn" data-print-request-label="${esc(r.id)}">Imprimir etiqueta</button><button class="secondary-btn" data-request-detail="${esc(r.id)}">Detalles</button></div></div>`).join('')||'<p class="muted small">No hay solicitudes pendientes.</p>';$('pickupOrders').innerHTML=req.filter(r=>r.estado==='preparado'&&(r.metodoAbastecimiento||'recoleccion_motigo')==='recoleccion_motigo').map(r=>`<div class="ops-card"><b>${esc(r.vendedorNombre||'Vendedor')}</b><p>Solicitud ${esc(r.folio||r.id)} · ${esc(r.direccionVendedor||'Ubicación del vendedor pendiente')}</p></div>`).join('')||'<p class="muted small">No hay recolecciones listas.</p>';bindOpsButtons();}
if(['admin','almacen'].includes(state.role.rol)){const snap=await getDocs(query(collection(db,'marketplacePedidos'),orderBy('creadoEn','desc'),limit(100)));state.allOrders=snap.docs.map(d=>({id:d.id,...d.data()}));$('warehousePickupOrders').innerHTML=state.allOrders.filter(o=>o.estado==='listo_para_recoger').map(o=>`<div class="ops-card"><b>${esc(o.folio||o.id)} · ${esc(o.nombreRecibe||'Cliente')}</b><p>El cliente debe presentar el código de recogida. Total: ${money(o.total)}</p><div class="ops-actions"><button class="secondary-btn" data-print-order-label="${esc(o.id)}">Imprimir etiqueta consolidada</button><button class="primary-btn" data-warehouse-pickup="${esc(o.id)}">Confirmar recogida</button></div></div>`).join('')||'<p class="muted small">No hay pedidos pendientes de recogida.</p>';bindWarehousePickupButtons();}
if(state.role.rol==='admin'){const snap=await getDocs(query(collection(db,'marketplacePedidos'),orderBy('creadoEn','desc'),limit(100)));state.allOrders=snap.docs.map(d=>({id:d.id,...d.data()}));const roleSnap=await getDocs(collection(db,'marketplaceRoles'));state.roles=roleSnap.docs.map(d=>({id:d.id,...d.data()}));$('adminRolesList').innerHTML=state.roles.map(r=>`<div class="seller-list-item"><div><b>${esc(r.nombre||r.id)}</b><small>${esc(r.rol)} · ${r.activo?'Activo':'Inactivo'} · ${esc(r.id)}</small></div></div>`).join('')||'<p class="muted small">Sin roles operativos.</p>';}
if(['admin','almacen'].includes(state.role.rol))$('readyOrders').innerHTML=state.allOrders.filter(o=>o.estado==='listo_para_ruta').map(o=>`<div class="ops-card"><b>${esc(o.folio||o.id)}</b><p>${esc(o.zona||'Zona no indicada')} · ${esc(o.nombreRecibe||'Cliente')} · ${money(o.total)}</p><p>${(o.items||[]).length} líneas de producto · ${esc(o.direccion||'Recoger en almacén')}</p><div class="ops-actions"><button class="secondary-btn" data-print-order-label="${esc(o.id)}">Imprimir etiqueta consolidada</button></div></div>`).join('')||'<p class="muted small">No hay pedidos listos para ruta.</p>';if(state.role.rol==='repartidor'){state.routes=state.opsRoutes.filter(r=>r.repartidorId===state.user.uid);$('riderRoutes').innerHTML=state.routes.map(routeCard).join('')||'<p class="muted small">No tienes rutas asignadas.</p>';bindRouteButtons();}if(['admin','almacen'].includes(state.role.rol)){const pickup=state.opsRoutes.filter(r=>r.tipo==='recoleccion');const delivery=state.opsRoutes.filter(r=>r.tipo==='entrega');$('pickupRoutes').innerHTML=pickup.map(routeCard).join('')||'<p class="muted small">Todavía no hay propuestas de recolección.</p>';$('deliveryRoutes').innerHTML=delivery.map(routeCard).join('')||'<p class="muted small">Todavía no hay propuestas de entrega.</p>';bindRouteButtons();}if(state.role.rol==='admin')loadOperationConfig();bindOpsButtons();
}catch(e){toast('No se pudo actualizar el panel operativo: '+friendlyError(e),'error');}}
function bindOpsButtons(){document.querySelectorAll('[data-print-request-label]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',()=>printRequestLabel(b.dataset.printRequestLabel));});document.querySelectorAll('[data-print-order-label]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',()=>printOrderLabel(b.dataset.printOrderLabel));});document.querySelectorAll('[data-receive-request]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',()=>receiveRequest(b.dataset.receiveRequest,b));});document.querySelectorAll('[data-request-detail]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',()=>{const r=state.allRequests.find(x=>x.id===b.dataset.requestDetail)||state.sellerRequests.find(x=>x.id===b.dataset.requestDetail);if(r)openModal(`<div class="modal-form"><h2>Solicitud ${esc(r.folio||r.id)}</h2><pre style="white-space:pre-wrap;font-size:11px">${esc(JSON.stringify(r,null,2))}</pre></div>`);});});}
async function receiveRequest(id,button){setBusy(button,true,'Registrando…');try{const r=state.allRequests.find(x=>x.id===id)||state.sellerRequests.find(x=>x.id===id);await updateDoc(doc(db,'marketplaceSolicitudesTienda',id),{estado:'recibido_almacen',recibidoPor:state.user.uid,recibidoEn:serverTimestamp(),actualizadoEn:serverTimestamp()});await addDoc(collection(db,'marketplaceRecepciones'),{solicitudId:id,pedidoId:r?.pedidoId||null,vendedorId:r?.vendedorId||null,recibidoPor:state.user.uid,estado:'completo',creadoEn:serverTimestamp()});toast('Recepción registrada.');}catch(e){toast(friendlyError(e),'error');}finally{setBusy(button,false);}}
function routeCard(r){return `<div class="ops-card"><div class="ops-card-header"><div><b>${esc(r.folio||r.id)} · ${r.tipo==='recoleccion'?'Recolección':'Entrega'}</b><p>${(r.paradas||[]).length} paradas · ${esc(r.estado||'propuesta')} · Distancia total: ${r.distanciaKmEstimada==null?'total pendiente de coordenadas':Number(r.distanciaKmEstimada).toFixed(1)+' km total'}${r.distanciaKmEstimada==null&&r.distanciaEntreParadasKm!=null?' · '+Number(r.distanciaEntreParadasKm).toFixed(1)+' km entre paradas':''}${r.duracionMinEstimada!=null?' · '+Math.round(r.duracionMinEstimada)+' min aprox.':''}${r.costoOperativoEstimado!=null?' · costo operativo aprox. '+money(r.costoOperativoEstimado):r.costoKilometrajeEstimado!=null?' · costo por km aprox. '+money(r.costoKilometrajeEstimado):''}</p></div><span class="status-pill">${esc(r.estado||'propuesta')}</span></div><div class="ops-actions">${r.estado==='propuesta'&&state.role?.rol==='admin'?`<button class="primary-btn" data-assign-route="${esc(r.id)}">Asignar repartidor</button>`:''}${r.estado==='asignada'&&r.repartidorId===state.user?.uid?`<button class="primary-btn" data-start-route="${esc(r.id)}">Iniciar ruta</button>`:''}${r.estado==='en_curso'&&r.repartidorId===state.user?.uid?`<button class="secondary-btn" data-complete-route="${esc(r.id)}">Finalizar ruta</button>`:''}</div>${(r.paradas||[]).map((p,i)=>`<div class="order-items-preview"><span class="order-item-chip">${i+1}. ${esc(p.nombre||p.direccion||p.folio||'Parada')}</span>${r.tipo==='entrega'&&r.estado==='en_curso'&&r.repartidorId===state.user?.uid&&p.estado!=='entregado'?`<button class="secondary-btn" data-route-delivery="${esc(r.id)}" data-order-id="${esc(p.pedidoId)}">Confirmar entrega</button>`:''}${r.tipo==='recoleccion'&&r.estado==='en_curso'&&r.repartidorId===state.user?.uid&&p.estado!=='recogido'?`<button class="secondary-btn" data-route-pickup="${esc(r.id)}" data-request-id="${esc(p.solicitudId)}">Confirmar recolección</button>`:''}</div>`).join('')}</div>`;}
function bindRouteButtons(){document.querySelectorAll('[data-route-delivery]').forEach(b=>b.addEventListener('click',()=>confirmDelivery(b.dataset.routeDelivery,b.dataset.orderId,b)));document.querySelectorAll('[data-route-pickup]').forEach(b=>b.addEventListener('click',()=>confirmPickup(b.dataset.routePickup,b.dataset.requestId,b)));document.querySelectorAll('[data-assign-route]').forEach(b=>b.addEventListener('click',()=>assignRoute(b.dataset.assignRoute)));document.querySelectorAll('[data-start-route]').forEach(b=>b.addEventListener('click',()=>startRoute(b.dataset.startRoute)));document.querySelectorAll('[data-complete-route]').forEach(b=>b.addEventListener('click',()=>completeRoute(b.dataset.completeRoute)));}
async function assignRoute(id){try{const riders=state.roles.filter(r=>r.rol==='repartidor'&&r.activo);if(!riders.length)return toast('Primero registra un repartidor en marketplaceRoles desde Firebase Console.','warning');openModal(`<div class="modal-form"><h2>Asignar ruta</h2><p>Elige un repartidor autorizado para Marketplace.</p><label class="form-field"><span>Repartidor</span><select id="routeRider">${riders.map(r=>`<option value="${esc(r.id)}">${esc(r.nombre||r.id)}</option>`).join('')}</select></label><div class="form-actions"><button class="secondary-btn" data-close-modal>Cancelar</button><button id="confirmRouteAssignment" class="primary-btn">Asignar</button></div></div>`);$('confirmRouteAssignment').addEventListener('click',async()=>{try{const route=state.opsRoutes.find(r=>r.id===id);const riderId=$('routeRider').value;const batch=writeBatch(db);batch.update(doc(db,'marketplaceRutas',id),{repartidorId:riderId,estado:'asignada',asignadoPor:state.user.uid,asignadoEn:serverTimestamp(),actualizadoEn:serverTimestamp()});if(route?.tipo==='entrega'){for(const orderId of route.pedidoIds||[])batch.update(doc(db,'marketplacePedidos',orderId),{repartidorId:riderId,rutaId:id,estado:'programado',actualizadoEn:serverTimestamp()});}else{for(const requestId of route.solicitudIds||[])batch.update(doc(db,'marketplaceSolicitudesTienda',requestId),{estado:'asignado_recoleccion',repartidorId:riderId,actualizadoEn:serverTimestamp()});}await batch.commit();closeModal();toast('Ruta asignada.');renderOpsData();}catch(e){toast(friendlyError(e),'error');}});}catch(e){toast(friendlyError(e),'error');}}
async function startRoute(id){try{const route=state.opsRoutes.find(r=>r.id===id);const batch=writeBatch(db);batch.update(doc(db,'marketplaceRutas',id),{estado:'en_curso',inicioEn:serverTimestamp(),actualizadoEn:serverTimestamp()});if(route?.tipo==='entrega'){for(const orderId of route.pedidoIds||[])batch.update(doc(db,'marketplacePedidos',orderId),{estado:'en_reparto',actualizadoEn:serverTimestamp()});}await batch.commit();toast('Ruta iniciada.');renderOpsData();}catch(e){toast(friendlyError(e),'error');}}
async function completeRoute(id){try{await updateDoc(doc(db,'marketplaceRutas',id),{estado:'finalizada',finalizadaEn:serverTimestamp(),actualizadoEn:serverTimestamp()});toast('Ruta finalizada.');renderOpsData();}catch(e){toast(friendlyError(e),'error');}}
async function buildPickupRoute(button){setBusy(button,true,'Calculando…');try{const res=await callCreatePickupRoute({});toast(res.data?.message||'Propuesta de recolección generada.');await renderOpsData();}catch(e){toast(friendlyError(e),'error');}finally{setBusy(button,false);}}
async function buildDeliveryRoutes(button){setBusy(button,true,'Calculando…');try{const res=await callCreateDeliveryRoutes({});toast(res.data?.message||'Propuesta de rutas generada.');await renderOpsData();}catch(e){toast(friendlyError(e),'error');}finally{setBusy(button,false);}}
function setupSubscriptions(){state.unsubs.forEach(fn=>{try{fn();}catch{}});state.unsubs=[];if(state.productsUnsub)state.productsUnsub();state.productsUnsub=onSnapshot(query(collection(db,'marketplaceProductos'),where('activo','==',true)),snap=>{state.products=snap.docs.map(d=>({id:d.id,...d.data()}));renderHome();if(state.view==='catalogo')renderCatalog();if(state.view==='favoritos')renderFavorites();if(state.view==='vender')renderSeller();const pid=new URL(location.href).searchParams.get('producto');if(pid&&!state._openedUrlProduct){state._openedUrlProduct=true;setTimeout(()=>openProduct(pid),250);}},err=>{console.error(err);$('featuredProducts').innerHTML='<p class="muted small">No se pudo cargar el catálogo. Verifica las reglas aditivas de Marketplace.</p>';});}
function clearUserSubscriptions(){for(const fn of state.unsubs){try{fn();}catch{}}state.unsubs=[];for(const k of ['orderUnsub','notificationUnsub','requestUnsub','roleUnsub','profileUnsub','sellerProductsUnsub','opsRequestUnsub','opsRouteUnsub']){if(state[k]){state[k]();state[k]=null;}}state.orders=[];state.notifications=[];state.sellerRequests=[];state.sellerProducts=[];state.allRequests=[];state.opsRoutes=[];state.role=null;state.mainAdmin=false;state.profile=null;}
function subscribeUserData(user){clearUserSubscriptions();if(!user){$('accountLabel').textContent='Ingresar';$('operationNav').classList.add('hidden');renderOrders();renderSeller();renderOperations();return;}$('accountLabel').textContent=(user.displayName||user.email||'Mi cuenta').split(' ')[0].slice(0,18);state.profileUnsub=onSnapshot(doc(db,'marketplacePerfiles',user.uid),snap=>{state.profile=snap.exists()?snap.data():null;renderSeller();},()=>{});state.sellerProductsUnsub=onSnapshot(query(collection(db,'marketplaceProductos'),where('vendedorId','==',user.uid),limit(200)),snap=>{state.sellerProducts=snap.docs.map(d=>({id:d.id,...d.data()}));if(state.view==='vender')renderSeller();},()=>{state.sellerProducts=[];});state.roleUnsub=onSnapshot(doc(db,'marketplaceRoles',user.uid),snap=>{state.role=state.mainAdmin?{rol:'admin',activo:true,origen:'usuarios'}:(snap.exists()?snap.data():null);$('operationNav').classList.toggle('hidden',!(state.role?.activo&&['admin','almacen','repartidor'].includes(state.role.rol)));setupOpsSubscriptions();renderOperations();},()=>{if(!state.mainAdmin)state.role=null;renderOperations();});getDoc(doc(db,'usuarios',user.uid)).then(snap=>{state.mainAdmin=snap.exists()&&snap.data()?.tipo==='admin';if(state.mainAdmin){state.role={rol:'admin',activo:true,origen:'usuarios'};$('operationNav').classList.remove('hidden');setupOpsSubscriptions();renderOperations();}}).catch(()=>{});state.orderUnsub=onSnapshot(query(collection(db,'marketplacePedidos'),where('clienteId','==',user.uid),limit(50)),snap=>{state.orders=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>timestamp(b.creadoEn)-timestamp(a.creadoEn));if(state.view==='pedidos')renderOrders();},()=>{state.orders=[];});state.notificationUnsub=onSnapshot(query(collection(db,'marketplaceNotificaciones'),where('usuarioId','==',user.uid),limit(40)),snap=>{state.notifications=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>timestamp(b.creadoEn)-timestamp(a.creadoEn));const unread=state.notifications.filter(n=>!n.leida).length;$('notificationBadge').textContent=unread;$('notificationBadge').classList.toggle('hidden',unread===0);if(state.notificationPanel)renderNotificationPanel();for(const n of state.notifications.filter(n=>!n.leida&&n.mostrarNavegador)){if('Notification'in window&&Notification.permission==='granted'&&!state._notified?.has(n.id)){state._notified=state._notified||new Set();state._notified.add(n.id);try{new Notification(n.titulo||'MOTI GO Marketplace',{body:n.mensaje||'',icon:'../assets/branding/icon-192.png'});}catch{}}}},()=>{});state.requestUnsub=onSnapshot(query(collection(db,'marketplaceSolicitudesTienda'),where('vendedorId','==',user.uid),limit(100)),snap=>{state.sellerRequests=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>timestamp(b.creadoEn)-timestamp(a.creadoEn));if(state.view==='vender')renderSeller();if(state.view==='operacion')renderOperations();},()=>{state.sellerRequests=[];});setupPushNotifications(user).catch(()=>{});if(new URL(location.href).searchParams.get('mp')==='conectado'){toast('Mercado Pago quedó vinculado.');const u=new URL(location.href);u.searchParams.delete('mp');history.replaceState({},'',u);}callMpConnectionStatus({}).then(r=>{if($('sellerMpNotice'))$('sellerMpNotice').textContent=r.data?.connected?'Tu cuenta de vendedor está vinculada a Mercado Pago. Los pagos se procesan desde el backend; nunca compartas tokens.':'Para cobrar ventas, vincula tu cuenta de Mercado Pago. La compra multitienda en un solo pago requiere habilitación Split 1:N.';}).catch(()=>{});renderOrders();renderSeller();}
async function setupPushNotifications(user){if(!('Notification'in window)||Notification.permission!=='granted')return;try{const configSnap=await getDoc(doc(db,'marketplaceConfig','operacion'));const vapidKey=(configSnap.exists()?configSnap.data().vapidKeyPublic:'')||VAPID_KEY;if(!vapidKey)return;if(!(await isSupported()))return;const registration=await navigator.serviceWorker.register('./mp-sw.js',{scope:'./'});const messaging=getMessaging(getApp());const token=await getToken(messaging,{vapidKey,serviceWorkerRegistration:registration});if(token)await setDoc(doc(db,'marketplaceDispositivos',user.uid+'_'+simpleHash(token)),{usuarioId:user.uid,token,actualizadoEn:serverTimestamp(),agente:navigator.userAgent.slice(0,180)},{merge:true});onMessage(messaging,payload=>toast(payload.notification?.body||'Tienes una notificación de Marketplace.'));}catch(e){console.warn('Push no configurado:',e);}}
function simpleHash(s){let h=0;for(let i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))|0;return Math.abs(h).toString(36);}
function renderNotificationPanel(){let panel=document.getElementById('notificationPanel');if(!panel){panel=document.createElement('div');panel.id='notificationPanel';panel.className='notification-panel';document.body.append(panel);}panel.innerHTML=`<div style="display:flex;justify-content:space-between;align-items:center"><h3>Notificaciones</h3><button class="icon-btn" id="closeNotificationPanel"><span class="material-symbols-outlined">close</span></button></div>${state.notifications.map(n=>`<div class="notification-item"><b>${esc(n.titulo||'MOTI GO Marketplace')}</b><p>${esc(n.mensaje||'')}</p><small>${fmtDateTime(n.creadoEn)}</small>${!n.leida?`<button class="text-btn" data-read-notification="${esc(n.id)}">Marcar como leída</button>`:''}</div>`).join('')||'<p class="muted small">No tienes notificaciones.</p>'}`;$('closeNotificationPanel').addEventListener('click',()=>{panel.remove();state.notificationPanel=false;});panel.querySelectorAll('[data-read-notification]').forEach(b=>b.addEventListener('click',async()=>{try{await updateDoc(doc(db,'marketplaceNotificaciones',b.dataset.readNotification),{leida:true,leidaEn:serverTimestamp()});}catch(e){toast(friendlyError(e),'error');}}));}
async function showNotifications(){if(!state.user)return openAuthModal('Inicia sesión para consultar tus notificaciones.');state.notificationPanel=!state.notificationPanel;const panel=document.getElementById('notificationPanel');if(!state.notificationPanel){panel?.remove();return;}renderNotificationPanel();try{const p=await Notification.requestPermission();if(p==='granted'&&state.user)setupPushNotifications(state.user).catch(()=>{});}catch{}}
async function saveSellerProfile(){const p=state.profile||{};openModal(`<form id="sellerProfileForm" class="modal-form"><h2>Perfil de vendedor</h2><p>Configura cómo recibirás pedidos y cómo se coordinará el traslado al almacén. Puedes vender como persona o como tienda.</p><div class="form-grid"><label class="form-field"><span>Nombre público *</span><input name="nombre" required maxlength="100" value="${esc(p.nombre||state.user?.displayName||'')}"></label><label class="form-field"><span>Teléfono de contacto *</span><input name="telefono" required maxlength="20" value="${esc(p.telefono||'')}"></label><label class="form-field"><span>Nombre de tienda (opcional)</span><input name="tiendaNombre" maxlength="100" value="${esc(p.tiendaNombre||'')}"></label><label class="form-field"><span>Modalidad de abastecimiento</span><select name="metodoAbastecimiento"><option value="recoleccion_motigo" ${!p.metodoAbastecimiento||p.metodoAbastecimiento==='recoleccion_motigo'?'selected':''}>MOTI GO recoge el producto</option><option value="entrega_vendedor" ${p.metodoAbastecimiento==='entrega_vendedor'?'selected':''}>Lo llevo al almacén</option></select></label><label class="form-field full-span"><span>Dirección o ubicación para recolección</span><input name="direccionVendedor" maxlength="240" value="${esc(p.direccionVendedor||'')}" placeholder="Dirección de tienda o punto de encuentro"></label><label class="form-field"><span>Comunidad</span><input name="zonaVendedor" maxlength="100" value="${esc(p.zonaVendedor||'Cabecera municipal')}"></label><label class="form-field"><span>Latitud (opcional)</span><input name="latitud" type="number" step="any" value="${esc(p.latitud??'')}"></label><label class="form-field"><span>Longitud (opcional)</span><input name="longitud" type="number" step="any" value="${esc(p.longitud??'')}"></label></div><div id="sellerProfileError" class="error-inline"></div><div class="form-actions"><button class="secondary-btn" type="button" data-close-modal>Cancelar</button><button class="primary-btn" type="submit">Guardar perfil</button></div></form>`);$('sellerProfileForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await setDoc(doc(db,'marketplacePerfiles',state.user.uid),{uid:state.user.uid,nombre:String(fd.get('nombre')).trim(),email:state.user.email,telefono:String(fd.get('telefono')).trim(),tiendaNombre:String(fd.get('tiendaNombre')).trim(),metodoAbastecimiento:String(fd.get('metodoAbastecimiento')),direccionVendedor:String(fd.get('direccionVendedor')).trim(),zonaVendedor:String(fd.get('zonaVendedor')).trim(),latitud:fd.get('latitud')?Number(fd.get('latitud')):null,longitud:fd.get('longitud')?Number(fd.get('longitud')):null,rol:'vendedor',activo:true,actualizadoEn:serverTimestamp(),...(p.creadoEn?{}:{creadoEn:serverTimestamp()})},{merge:true});closeModal();toast('Perfil de vendedor guardado.');}catch(err){$('sellerProfileError').textContent=friendlyError(err);}});}
async function markOrderPicked(orderId,button){setBusy(button,true,'Guardando…');try{await updateDoc(doc(db,'marketplacePedidos',orderId),{estado:'recogido_cliente',recogidoClienteEn:serverTimestamp(),actualizadoEn:serverTimestamp()});toast('Recogida confirmada.');}catch(e){toast(friendlyError(e),'error');}finally{setBusy(button,false);}}
function printHtmlDocument(title,body){const w=window.open('','_blank','width=480,height=640');if(!w){toast('El navegador bloqueó la ventana de impresión. Permite ventanas emergentes para imprimir etiquetas.','warning');return;}w.document.open();w.document.write(`<!doctype html><html lang="es"><head><meta charset="utf-8"><title>${esc(title)}</title><style>@page{size:80mm auto;margin:3mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;margin:0;color:#111}.label{width:74mm;border:1px solid #222;padding:4mm;margin:0 auto 4mm;page-break-after:always}.head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #333;padding-bottom:3mm}.brand{font-weight:900;font-size:14px;color:#087b43}.sub{font-size:8px;color:#444;margin-top:2px}.folio{font-size:15px;font-weight:900;margin:4mm 0 2mm;word-break:break-all}.field{font-size:10px;margin:2mm 0;line-height:1.35}.items{font-size:10px;line-height:1.45;border-top:1px dashed #777;margin-top:3mm;padding-top:2mm}.qr{display:flex;justify-content:center;margin:3mm auto}.qr img{width:30mm;height:30mm}.code{text-align:center;font-size:8px;word-break:break-all}.foot{font-size:8px;text-align:center;border-top:1px solid #bbb;padding-top:2mm;margin-top:3mm}@media screen{body{padding:12px;background:#eee}.label{background:white;box-shadow:0 2px 12px #0002}}</style></head><body>${body}<script>window.onload=()=>setTimeout(()=>window.print(),350);</script></body></html>`);w.document.close();}
function printRequestLabel(id){const r=state.allRequests.find(x=>x.id===id)||state.sellerRequests.find(x=>x.id===id);if(!r)return toast('No se encontró la solicitud para imprimir.','error');const qr=`MOTIGO|SOLICITUD|${r.id}`;const qrUrl=`https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=${encodeURIComponent(qr)}`;const items=(r.items||[]).map(i=>`<div>${esc(i.nombre)} × ${Number(i.cantidad)||1}</div>`).join('');const body=`<div class="label"><div class="head"><div><div class="brand">MOTI GO</div><div class="sub">MARKETPLACE · PAQUETE DE VENDEDOR</div></div><b>NO DOBLAR</b></div><div class="folio">${esc(r.folio||r.id)}</div><div class="field"><b>Vendedor:</b> ${esc(r.vendedorNombre||'Vendedor local')}</div><div class="field"><b>Solicitud:</b> ${esc(r.id)}</div><div class="items"><b>Contenido declarado</b>${items}</div><div class="qr"><img src="${qrUrl}" alt="QR de identificación"></div><div class="code">${esc(qr)}</div><div class="foot">Etiqueta interna para recepción y consolidación. No contiene datos de contacto del comprador.</div></div>`;printHtmlDocument(`Etiqueta ${r.folio||r.id}`,body);}
function printOrderLabel(id){const o=state.allOrders.find(x=>x.id===id)||state.orders.find(x=>x.id===id);if(!o)return toast('No se encontró el pedido para imprimir.','error');const qr=`MOTIGO|PEDIDO|${o.id}`;const qrUrl=`https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=${encodeURIComponent(qr)}`;const items=(o.items||[]).map(i=>`<div>${esc(i.nombre)} × ${Number(i.cantidad)||1}</div>`).join('');const body=`<div class="label"><div class="head"><div><div class="brand">MOTI GO</div><div class="sub">MARKETPLACE · ENVÍO CONSOLIDADO</div></div><b>${o.modoEntrega==='almacen'?'RECOGER':'ENTREGAR'}</b></div><div class="folio">${esc(o.folio||o.id)}</div><div class="field"><b>Recibe:</b> ${esc(o.nombreRecibe||'Cliente')}</div><div class="field"><b>Zona:</b> ${esc(o.zona||'')}</div><div class="field"><b>Dirección:</b> ${esc(o.direccion||'ALMACÉN CENTRAL MOTI GO')}</div><div class="field"><b>Referencias:</b> ${esc(o.referencias||'—')}</div><div class="items"><b>Contenido consolidado</b>${items}</div><div class="qr"><img src="${qrUrl}" alt="QR del pedido"></div><div class="code">${esc(qr)}</div><div class="foot">Verificar que todas las partidas del pedido estén reunidas antes de despachar.</div></div>`;printHtmlDocument(`Etiqueta consolidada ${o.folio||o.id}`,body);}
function stopWarehouseCamera(){state.cameraScanActive=false;if(state.cameraStream){state.cameraStream.getTracks().forEach(t=>t.stop());state.cameraStream=null;}const video=$('warehouseCameraVideo');if(video)video.srcObject=null;}
async function startWarehouseCameraScan(){if(!navigator.mediaDevices?.getUserMedia||!('BarcodeDetector'in window)){toast('Este navegador no permite escaneo QR con cámara. Usa un lector que escriba el código o pega el código manualmente.','warning');return;}try{openModal(`<div class="modal-form"><h2>Escanear etiqueta</h2><p>Apunta la cámara al QR de la etiqueta de paquete o del pedido consolidado.</p><video id="warehouseCameraVideo" autoplay playsinline style="width:100%;max-height:55vh;background:#101a13;border-radius:12px"></video><p id="cameraScanStatus" class="muted small">Buscando código QR…</p><div class="form-actions"><button class="secondary-btn" type="button" data-close-modal>Cancelar</button></div></div>`);const video=$('warehouseCameraVideo');state.cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});video.srcObject=state.cameraStream;await video.play();const detector=new BarcodeDetector({formats:['qr_code']});state.cameraScanActive=true;const scan=async()=>{if(!state.cameraScanActive||!$('warehouseCameraVideo'))return;try{const codes=await detector.detect(video);if(codes.length&&codes[0].rawValue){const value=codes[0].rawValue;stopWarehouseCamera();closeModal();$('warehouseScanInput').value=value;handleWarehouseScan();return;}}catch{}if(state.cameraScanActive)requestAnimationFrame(scan);};requestAnimationFrame(scan);}catch(e){stopWarehouseCamera();closeModal();toast('No se pudo abrir la cámara. Revisa el permiso del navegador.','error');}}
async function handleWarehouseScan(){const input=$('warehouseScanInput');const raw=input.value.trim();if(!raw)return toast('Escanea o escribe un código.','warning');let kind='',id=raw;const parts=raw.split('|');if(parts.length>=3&&parts[0]==='MOTIGO'){kind=parts[1];id=parts.slice(2).join('|');}if(kind==='PEDIDO'||state.allOrders.some(o=>o.id===id||o.folio===id)){const o=state.allOrders.find(x=>x.id===id||x.folio===id);if(!o)return toast('No se encontró ese pedido.','error');openOrderDetail(o.id);input.value='';return;}const r=state.allRequests.find(x=>x.id===id||x.folio===id);if(!r)return toast('No se encontró esa solicitud. Comprueba que sea una etiqueta de Marketplace.','error');input.value='';openModal(`<div class="modal-form"><span class="eyebrow green">RECEPCIÓN</span><h2>Solicitud ${esc(r.folio||r.id)}</h2><p><b>Vendedor:</b> ${esc(r.vendedorNombre||'Vendedor local')}</p><p><b>Estado:</b> ${esc(statusLabels[r.estado]||r.estado)}</p><div class="order-items-preview">${(r.items||[]).map(i=>`<span class="order-item-chip">${esc(i.nombre)} × ${Number(i.cantidad)||1}</span>`).join('')}</div><p class="muted small">Verifica físicamente los artículos y cantidades antes de confirmar la recepción.</p><div class="form-actions"><button class="secondary-btn" data-close-modal>Cancelar</button><button id="confirmScannedReceipt" class="primary-btn">Confirmar recepción</button></div></div>`);$('confirmScannedReceipt').addEventListener('click',async()=>{const btn=$('confirmScannedReceipt');await receiveRequest(r.id,btn);closeModal();});}
async function startMpOAuth(button){if(!state.user)return openAuthModal('Inicia sesión para vincular Mercado Pago.');try{const res=await callStartMpOAuth({});if(res.data?.url)location.href=res.data.url;else toast('No se recibió la URL de autorización de Mercado Pago.','error');}catch(e){toast(friendlyError(e),'error');}}
async function bindWarehousePickupButtons(){document.querySelectorAll('[data-print-order-label]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',()=>printOrderLabel(b.dataset.printOrderLabel));});document.querySelectorAll('[data-warehouse-pickup]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',async()=>{const code=prompt('Pide al cliente su código de recogida:');if(!code)return;setBusy(b,true,'Verificando…');try{await callConfirmWarehousePickup({pedidoId:b.dataset.warehousePickup,codigo:code});toast('Recogida en almacén confirmada.');await renderOpsData();}catch(e){toast(friendlyError(e),'error');}finally{setBusy(b,false);}});});}
async function loadOperationConfig(){if(state.role?.rol!=='admin'||state.operationConfig)return;try{const snap=await getDoc(doc(db,'marketplaceConfig','operacion'));if(!snap.exists())return;const c=snap.data();state.operationConfig=c;$('configZones').value=(c.zonasPermitidas||[]).join(', ');$('configExtendedZones').value=(c.zonasExtendidas||[]).join(', ');$('configDeliveryFee').value=c.tarifaEntregaBase??'';$('configCommission').value=c.comisionMarketplacePct??'';$('configMaxStops').value=c.maxParadasRuta??6;$('configMaxTownDays').value=c.plazoMaxDiasCabecera??3;$('configMaxRemoteDays').value=c.plazoMaxDiasComunidad??4;$('configWarehouseLat').value=c.almacenLat??'';$('configWarehouseLng').value=c.almacenLng??'';$('configPickupKmCost').value=c.costoKmRecoleccion??'';$('configDeliveryKmCost').value=c.costoKmEntrega??'';$('configAvgSpeed').value=c.velocidadPromedioKmH??'';$('configStopMinutes').value=c.minutosPorParada??'';$('configOperatorHourCost').value=c.costoHoraRepartidor??'';$('configZoneTariffs').value=c.tarifasPorZona?JSON.stringify(c.tarifasPorZona,null,2):'';$('configVapidKey').value=c.vapidKeyPublic||'';}catch(e){$('configSaveMessage').textContent='No se pudo leer la configuración. Verifica reglas y rol de administrador.';}}
async function saveOperationConfig(e){e.preventDefault();if(state.role?.rol!=='admin')return toast('Solo el administrador puede cambiar tarifas y cobertura.','error');const zones=$('configZones').value.split(',').map(x=>x.trim()).filter(Boolean);const extendedZones=$('configExtendedZones').value.split(',').map(x=>x.trim()).filter(Boolean);let tariffs={};try{tariffs=$('configZoneTariffs').value.trim()?JSON.parse($('configZoneTariffs').value):{};if(!tariffs||Array.isArray(tariffs)||typeof tariffs!=='object')throw new Error();for(const v of Object.values(tariffs))if(!Number.isFinite(Number(v))||Number(v)<0)throw new Error();}catch{return $('configSaveMessage').textContent='Las tarifas por zona deben ser un objeto JSON con valores numéricos no negativos.';}const optionalNumber=id=>$(id).value.trim()===''?null:Number($(id).value);const warehouseLat=optionalNumber('configWarehouseLat'),warehouseLng=optionalNumber('configWarehouseLng'),pickupKm=optionalNumber('configPickupKmCost'),deliveryKm=optionalNumber('configDeliveryKmCost'),avgSpeed=optionalNumber('configAvgSpeed'),stopMinutes=optionalNumber('configStopMinutes'),operatorHour=optionalNumber('configOperatorHourCost');const fee=Number($('configDeliveryFee').value),commission=Number($('configCommission').value),maxStops=Number($('configMaxStops').value),town=Number($('configMaxTownDays').value),remote=Number($('configMaxRemoteDays').value);if((warehouseLat===null)!==(warehouseLng===null))return $('configSaveMessage').textContent='Para calcular distancia total, captura latitud y longitud del almacén.';if(!zones.length||!Number.isFinite(fee)||fee<0||!Number.isFinite(commission)||commission<0||commission>50||maxStops<1||maxStops>12||town<1||town>4||remote<1||remote>4){$('configSaveMessage').textContent='Revisa los valores. Agrega al menos una zona y valores válidos.';return;}try{const configData={configurado:true,zonasPermitidas:zones,zonasExtendidas:extendedZones,vapidKeyPublic:$('configVapidKey').value.trim(),tarifaEntregaBase:fee,comisionMarketplacePct:commission,maxParadasRuta:maxStops,plazoMinDias:1,plazoMaxDiasCabecera:town,plazoMaxDiasComunidad:remote,almacenLat:warehouseLat,almacenLng:warehouseLng,costoKmRecoleccion:pickupKm,costoKmEntrega:deliveryKm,velocidadPromedioKmH:avgSpeed,minutosPorParada:stopMinutes,costoHoraRepartidor:operatorHour,tarifasPorZona:tariffs,actualizadoPor:state.user.uid,actualizadoEn:serverTimestamp()};await setDoc(doc(db,'marketplaceConfig','operacion'),configData,{merge:true});state.operationConfig=configData;setupPushNotifications(state.user).catch(()=>{});$('configSaveMessage').textContent='Configuración guardada. El servidor la utilizará para validar cobertura, costo y fecha estimada.';toast('Configuración operativa guardada.');}catch(err){$('configSaveMessage').textContent=friendlyError(err);}}
async function confirmDelivery(routeId,orderId,button){const code=prompt('Solicita al cliente el código de entrega y escríbelo aquí:');if(!code)return;setBusy(button,true,'Verificando…');try{const fn=httpsCallable(functions,'marketplaceConfirmarParada');await fn({rutaId:routeId,pedidoId:orderId,codigo:code,resultado:'entregado'});toast('Entrega confirmada correctamente.');await renderOpsData();}catch(e){toast(friendlyError(e),'error');}finally{setBusy(button,false);}}
async function confirmPickup(routeId,requestId,button){const confirm=window.confirm('¿Confirmas que recogiste la mercancía del vendedor y la llevas al almacén?');if(!confirm)return;setBusy(button,true,'Registrando…');try{const fn=httpsCallable(functions,'marketplaceConfirmarRecoleccion');await fn({rutaId:routeId,solicitudId:requestId});toast('Recolección registrada. Lleva los artículos al almacén para su recepción.');await renderOpsData();}catch(e){toast(friendlyError(e),'error');}finally{setBusy(button,false);}}
function bindEvents(){document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',e=>{if(b.tagName==='A')e.preventDefault();showView(b.dataset.view);}));$('cartBtn').addEventListener('click',openCart);$('cartDrawer').querySelectorAll('[data-close-cart]').forEach(b=>b.addEventListener('click',closeCart));$('checkoutBtn').addEventListener('click',openCheckout);$('accountBtn').addEventListener('click',()=>state.user?openAccountMenu():openAuthModal());$('sellerLoginBtn').addEventListener('click',()=>openAuthModal());$('newProductBtn').addEventListener('click',()=>{if(!state.profile?.nombre||!state.profile?.telefono)saveSellerProfile();else openProductForm();});$('connectMPBtn').addEventListener('click',startMpOAuth);$('notificationsBtn').addEventListener('click',showNotifications);$('searchInput').addEventListener('input',()=>{state.search=$('searchInput').value;if(state.search)showView('catalogo');renderCatalog();$('clearSearch').style.visibility=state.search?'visible':'hidden';});$('clearSearch').addEventListener('click',()=>{$('searchInput').value='';state.search='';$('clearSearch').style.visibility='hidden';renderCatalog();});$('searchBtn').addEventListener('click',()=>{state.search=$('searchInput').value;showView('catalogo');renderCatalog();});$('sortProducts').addEventListener('change',renderCatalog);['categoryFilter','minPrice','maxPrice','inStockOnly'].forEach(id=>$(id).addEventListener('change',renderCatalog));$('clearFilters').addEventListener('click',()=>{$('categoryFilter').value='todos';$('minPrice').value='';$('maxPrice').value='';$('inStockOnly').checked=false;renderCatalog();});$('refreshOrders').addEventListener('click',renderOrders);$('refreshOperations').addEventListener('click',renderOpsData);$('operationConfigForm').addEventListener('submit',saveOperationConfig);$('operationConfigForm').addEventListener('focusin',()=>loadOperationConfig(),{once:true});$('buildPickupRoute').addEventListener('click',()=>buildPickupRoute($('buildPickupRoute')));$('buildDeliveryRoute').addEventListener('click',()=>buildDeliveryRoutes($('buildDeliveryRoute')));$('warehouseScanBtn').addEventListener('click',handleWarehouseScan);$('warehouseCameraScanBtn').addEventListener('click',startWarehouseCameraScan);$('warehouseScanInput').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();handleWarehouseScan();}});document.querySelectorAll('[data-op-tab]').forEach(b=>b.addEventListener('click',()=>{state.opTab=b.dataset.opTab;renderOperations();}));$('mobileMenu').addEventListener('click',()=>$('mainNav').classList.toggle('mobile-open'));$('categoryChips').querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{state.category=b.dataset.category;$('categoryFilter').value=state.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x.dataset.category===state.category));showView('catalogo');renderCatalog();}));$('heroPrev').addEventListener('click',()=>setHeroSlide(state.activeSlide-1));$('heroNext').addEventListener('click',()=>setHeroSlide(state.activeSlide+1));$('heroDots').querySelectorAll('[data-slide]').forEach(b=>b.addEventListener('click',()=>setHeroSlide(Number(b.dataset.slide))));}
function setHeroSlide(n){const slides=[...document.querySelectorAll('.hero-slide')];state.activeSlide=(n+slides.length)%slides.length;slides.forEach((s,i)=>s.classList.toggle('active',i===state.activeSlide));$('heroDots').querySelectorAll('button').forEach((b,i)=>b.classList.toggle('active',i===state.activeSlide));}
function openAccountMenu(){openModal(`<div class="modal-form"><h2>Mi cuenta</h2><p>${esc(state.user?.email||'Sesión activa')}</p><div class="panel-card"><b>${esc(state.profile?.nombre||state.user?.displayName||'Usuario MOTI GO')}</b><p class="muted small">Marketplace usa un perfil separado para vender y gestionar pedidos.</p><button class="secondary-btn full" id="editSellerProfile">Editar perfil de vendedor</button></div><div class="form-actions"><button class="secondary-btn" data-close-modal>Cerrar</button><button class="primary-btn" id="logoutBtn">Cerrar sesión</button></div></div>`);$('editSellerProfile').addEventListener('click',saveSellerProfile);$('logoutBtn').addEventListener('click',async()=>{await signOut(auth);closeModal();toast('Sesión cerrada.');});}
async function processPaymentReturn(){const u=new URL(location.href),payment=u.searchParams.get('payment'),pedido=u.searchParams.get('pedido');if(!payment&&!u.searchParams.has('collection_status')&&!u.searchParams.has('status'))return;const pending=loadJSON('motiMpPendingCheckout',null);if(!state.user||!pending)return;try{const response=await callMarkPaymentReturn({pedidoId:pedido||pending.pedidoId,query:Object.fromEntries(u.searchParams.entries())});const paid=response.data?.pagoEstado;if(paid==='aprobado')toast('Pago confirmado por el servidor. Tu pedido ya está en seguimiento.');else if(['rechazado','cancelado','expirado'].includes(paid))toast('El pago no quedó aprobado. Revisa tu pedido antes de volver a intentar.','warning');else toast('Regresaste de Mercado Pago. Estamos verificando el pago con el servidor; el pedido no se marcará pagado solo por volver a esta página.','warning');localStorage.removeItem('motiMpPendingCheckout');}catch(e){toast('Regresaste de Mercado Pago, pero la confirmación debe validarse con el webhook. '+friendlyError(e),'warning');}u.searchParams.delete('payment');u.searchParams.delete('pedido');u.searchParams.delete('status');u.searchParams.delete('collection_status');history.replaceState({},'',u);}
function startup(){bindEvents();updateCartBadges();const params=new URL(location.href).searchParams;const initial=params.get('vista')||'inicio';if(params.get('op'))state.opTab=params.get('op');showView(initial,false);setupSubscriptions();if(params.get('carrito')==='1')setTimeout(openCart,250);if(params.get('checkout')==='1')setTimeout(openCheckout,350);onAuthStateChanged(auth,user=>{state.user=user;subscribeUserData(user);if(user)processPaymentReturn();else{$('accountLabel').textContent='Ingresar';}});if('serviceWorker'in navigator){/* No reemplazamos el service-worker.js de MOTI GO. El SW de push es independiente. */} }
startup();
